"""Immutable source-order snapshots; no release policy is applied here."""

from dataclasses import dataclass


@dataclass(frozen=True)
class CatalogSnapshot:
    records: tuple

    def projects(self):
        return tuple(dict.fromkeys(row.project for row in self.records))

"""Public client API over a retained catalog snapshot."""

from .cache import CatalogSnapshot
from .display import ordered_versions
from .manifest import decode_manifest
from .selection import choose_release


class Catalog:
    def __init__(self, records):
        self.snapshot = CatalogSnapshot(tuple(records))

    @classmethod
    def from_manifest(cls, text):
        return cls(decode_manifest(text))

    def choose(self, project, platform, *, include_previews=False):
        return choose_release(
            self.snapshot.records,
            project=project,
            platform=platform,
            include_previews=include_previews,
        )

    def versions(self, project):
        return ordered_versions(
            row for row in self.snapshot.records if row.project == project
        )

"""A side-effect-free command projection used by an external UI."""

from .paths import artifact_filename


def selection_summary(catalog, project, platform, *, include_previews=False):
    selected = catalog.choose(project, platform, include_previews=include_previews)
    if selected is None:
        return {"status": "unavailable"}
    return {
        "status": "selected",
        "version": selected.version,
        "uri": selected.uri,
        "filename": artifact_filename(selected),
    }

"""Version display ordering shares catalog version semantics."""

from .versions import parse_version, version_order


def ordered_versions(records):
    valid = []
    for row in records:
        try:
            parse_version(row.version)
        except ValueError:
            continue
        valid.append(row.version)
    return tuple(sorted(valid, key=version_order))

"""Catalog interchange; published record order is retained."""

import json
from dataclasses import asdict

from .models import Artifact


def decode_manifest(text):
    rows = json.loads(text)
    if not isinstance(rows, list):
        raise ValueError("manifest must contain an array")
    return tuple(Artifact(**row) for row in rows)


def encode_manifest(records):
    return json.dumps([asdict(row) for row in records], ensure_ascii=False)

"""Repository-independent catalog data."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Artifact:
    project: str
    platform: str
    version: str
    uri: str
    enabled: bool = True

    def __post_init__(self):
        if not self.project or not self.platform or not self.uri:
            raise ValueError("artifact identity fields must be present")

"""Safe presentation names for a selected artifact; no download side effects."""

import re


def artifact_filename(artifact):
    if not re.fullmatch(r"[A-Za-z0-9_-]+", artifact.project):
        raise ValueError("unsafe project filename")
    suffix = artifact.platform.strip().casefold()
    if not re.fullmatch(r"[A-Za-z0-9_-]+", suffix):
        raise ValueError("unsafe platform filename")
    return f"{artifact.project}-{artifact.version}-{suffix}.pkg"

"""Eligibility is distinct from ordering eligible releases."""

from .versions import parse_version


def eligible(artifact, *, project, platform, include_previews):
    if not artifact.enabled or artifact.project != project:
        return False
    if artifact.platform.strip().casefold() != platform.strip().casefold():
        return False
    try:
        parts = parse_version(artifact.version)
    except ValueError:
        return False
    return include_previews or not parts.prerelease

"""Select from catalog records without modifying their order or ownership."""

from .policy import eligible
from .versions import version_order


def choose_release(records, *, project, platform, include_previews=False):
    candidates = (
        row
        for row in records
        if eligible(
            row, project=project, platform=platform, include_previews=include_previews
        )
    )
    return max(candidates, key=lambda row: version_order(row.version), default=None)
